<script type="application/ld+json">
{"@context": "https://schema.org", "@type": "FAQPage", "mainEntity": [{"@type": "Question", "name": "Меняет ли казначейское сопровождение налоги?", "acceptedAnswer": {"@type": "Answer", "text": "Нет. Оно меняет маршрут целевых денег и режим их расходования, но не систему налогообложения. Налоги исполнитель платит по своей системе — общей или упрощённой — как по обычному контракту."}}, {"@type": "Question", "name": "Нужно ли платить НДС с аванса, зачисленного на лицевой счёт?", "acceptedAnswer": {"@type": "Answer", "text": "Да. По статье 167 НК налоговая база по НДС определяется на дату получения аванса независимо от того, на какой счёт он поступил. При отгрузке авансовый НДС принимается к вычету."}}, {"@type": "Question", "name": "Облагается ли налогом на прибыль оплата по госконтракту?", "acceptedAnswer": {"@type": "Answer", "text": "Да. Для исполнителя это выручка от реализации (статья 249 НК). Целевой характер средств не делает их необлагаемым целевым финансированием: перечень в статье 251 НК закрытый и оплату за товары и работы не включает."}}, {"@type": "Question", "name": "Как учитывать доход на УСН?", "acceptedAnswer": {"@type": "Answer", "text": "На упрощённой системе доход признаётся кассовым методом — на дату поступления денег на лицевой счёт (статья 346.17 НК), включая аванс. «Целевыми» для целей налога эти средства не являются."}}, {"@type": "Question", "name": "Можно ли платить налоги с лицевого счёта в казначействе?", "acceptedAnswer": {"@type": "Answer", "text": "Да. Уплата налогов, сборов и страховых взносов относится к разрешённым операциям по лицевому счёту участника сопровождения и проводится через санкционирование."}}, {"@type": "Question", "name": "Чем раздельный учёт отличается от налогового?", "acceptedAnswer": {"@type": "Answer", "text": "Раздельный учёт показывает, как расходуются целевые средства по каждому контракту, и нужен для контроля и ценообразования. Налоговый учёт исчисляет налоги по правилам НК. Это разные виды учёта, которые ведутся параллельно."}}, {"@type": "Question", "name": "Влияет ли спецсчёт по ГОЗ на налоги?", "acceptedAnswer": {"@type": "Answer", "text": "Нет. Режим отдельного счёта по 275-ФЗ определяет порядок расходования средств и вывода прибыли, но НДС, налог на прибыль и УСН считаются по общим нормам НК."}}, {"@type": "Question", "name": "Можно ли выплатить зарплату с лицевого счёта?", "acceptedAnswer": {"@type": "Answer", "text": "Да. Выплата заработной платы работникам, занятым в исполнении контракта, — разрешённая операция по лицевому счёту, как и уплата связанных с ней налогов и взносов."}}, {"@type": "Question", "name": "Платит ли НДС исполнитель на УСН?", "acceptedAnswer": {"@type": "Answer", "text": "По общему правилу на УСН НДС не уплачивается, кроме случаев, прямо установленных НК. Казначейское сопровождение само по себе обязанности по НДС не добавляет — она зависит от системы налогообложения и норм НК."}}, {"@type": "Question", "name": "Нужна ли консультация по налогам при сопровождении?", "acceptedAnswer": {"@type": "Answer", "text": "Желательно. Налогообложение зависит от системы, условий контракта и структуры расходов. Эта статья носит справочный характер; конкретные расчёты стоит согласовать с бухгалтером или налоговым консультантом."}}]}
